import sys, json, os, re, hashlib, base64, secrets, datetime

# THE PROJECTION OF A FILE SPACE (GH #905, R-27-5/R-27-6 K1). Tools need real
# files; the space keeps blocks and versions. This cell lays the state of one
# workspace out as a directory `<base_path>/<ws-name>/` (after the first time
# only what changed), hands a permitted program to `./run`, and afterwards
# compares the directory against what it wrote -- no watcher, no polling: the
# run ends, then the directory is read once. What the program changed is
# either taken over at once (a formatter, `auto_adopt`) or kept as a proposal
# for `ws_adopt`. Every byte that goes back into the space goes through
# `in_write` of the space with `hop.ws` -- this hive never touches the space's
# tables.
#
# The cell runs `cold`: a request becomes a job parked in `pending` (key
# `op_id` = the job id, `cell` = 'mat'). Every answer of the space or of
# `./run` is parked next to it as its own row (`a:<sub>`) and the job reads
# on only when every answer it waits for is there -- the store answers in
# arrival order, so exactly one bundle sees the last answer. A request out of
# this hive is sent only after the store confirmed the job row that waits for
# it (phase `send`): its answer can never overtake the job.
#
# Nothing outside `<base_path>/` is written: the sandbox of this cell grants
# write access to `base_path` alone (set by the owner's override, the template
# grants none), and every path is checked against the workspace directory
# before it is written or removed.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}

ME = "mat"
CALLER = "projection"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
OPS = ("ws_materialize", "ws_exec", "ws_adopt")
NAME_RE = re.compile(r"^[A-Za-z0-9_-][A-Za-z0-9._-]{0,63}$")
V12_RE = re.compile(r"^[0-9a-f]{12,64}$")
STAGE = ".mat"
TAIL_BYTES = 8192
ROW_LIMIT = 5000
JOB_TTL_MS = 3600000
HASH_CHUNK = 1048576


# ================================================================ PURE HALF
def v12(version):
    return str(version or "")[:12]


def jload(value, default):
    if isinstance(value, (list, dict)):
        return value
    try:
        out = json.loads(str(value))
    except Exception:
        return default
    return out if isinstance(out, type(default)) else default


def dir_name(name):
    """Whether a workspace name may name a directory under `base_path`:
    the space's name rule (1 to 64 of [A-Za-z0-9._-]) without a leading dot --
    `.` and `..` would leave the base, and `.mat` is this cell's staging."""
    return isinstance(name, str) and bool(NAME_RE.match(name))


def check_base(base, cwd):
    """'' when `base` may be the projection's base, else the refusal code:
    absolute, normalised, not `/`, and neither the colony root `cwd` nor
    inside it (No-Delete holds there). `cwd` is '' when the cell does not
    know the root (see `colony_root`) -- then only the form is checked."""
    if not isinstance(base, str) or not base or not base.startswith("/"):
        return "no_base_path"
    if base != "/" and base.endswith("/"):
        base = base.rstrip("/")
    if base == "/" or os.path.normpath(base) != base:
        return "bad_base_path"
    c = os.path.normpath(cwd or "/")
    if c != "/" and (base == c or base.startswith(c + "/")):
        return "bad_base_path"
    return ""


def colony_root(cwd, exists):
    """The colony root as the cell sees it: its working directory when that
    directory holds a `colony.json`, else ''. A code cell is told no root and
    inherits the daemon's cwd; a daemon started from a home directory must not
    lock every base under home (OR-FJ-74)."""
    if cwd and exists(os.path.join(cwd, "colony.json")):
        return os.path.normpath(cwd)
    return ""


def colony_above(base, exists):
    """The nearest directory at or above `base` that holds a `colony.json`,
    else '': a base inside ANY colony tree is refused, whatever the cwd."""
    d = os.path.normpath(base)
    while True:
        if exists(os.path.join(d, "colony.json")):
            return d
        up = os.path.dirname(d)
        if up == d:
            return ""
        d = up


def rel_of(path, root):
    """The directory-relative path of a space path under the workspace root,
    or None: a path outside the root, with `..`, `.` or empty segments, or
    not absolute never becomes a file on disk (`outside_root`, OR-FJ-70)."""
    if not isinstance(path, str) or not path.startswith("/") or "\x00" in path:
        return None
    r = (root or "/").rstrip("/")
    if r and not (path.startswith(r + "/")):
        return None
    rel = path[len(r) + 1:] if r else path[1:]
    parts = rel.split("/")
    if not rel or any(p in ("", ".", "..") for p in parts):
        return None
    return rel


def path_of(rel, root):
    """The space path of a directory-relative path (inverse of `rel_of`)."""
    r = (root or "/").rstrip("/")
    return r + "/" + rel


def glob_re(glob):
    """A glob over `/`-separated relative paths as a regex: `**` crosses
    directories, `*` and `?` stay inside one segment."""
    out, i = [], 0
    while i < len(glob):
        c = glob[i]
        if glob.startswith("**", i):
            out.append(".*")
            i += 2
            continue
        out.append("[^/]*" if c == "*" else "[^/]" if c == "?" else re.escape(c))
        i += 1
    return re.compile("^" + "".join(out) + "$")


def ignored(rel, globs):
    """Whether `rel` (or a directory above it) matches one of `globs`; a
    `.git` segment at any depth is always left out (OR-FJ-72)."""
    if ".git" in rel.split("/"):
        return True
    for g in globs or []:
        rx = glob_re(str(g))
        if rx.match(rel):
            return True
        parts = rel.split("/")
        for n in range(1, len(parts)):
            if rx.match("/".join(parts[:n]) + "/"):
                return True
    return False


def allowed(argv, allow):
    """Whether argv[0] is one of the permitted program names, exactly."""
    return bool(argv) and isinstance(argv[0], str) and argv[0] in [str(a) for a in allow or []]


def auto_hit(argv, prefixes):
    """Whether argv starts with one of the `auto_adopt` prefixes, word by
    word (`"cargo fmt"` takes `cargo fmt --all`, not `cargo fmtx`)."""
    for p in prefixes or []:
        words = str(p).split()
        if words and list(argv[:len(words)]) == words:
            return True
    return False


def plan_materialize(tree, manifest, disk, force):
    """What one materialisation does. `tree` is the answer of `ws_tree`
    (`[{file, path, version}]`), `manifest` what was written last time
    (`{path: {file, version, sha256}}`), `disk` the sha256 of every file the
    two name as it is on disk now (None: absent). A file a tool changed and
    nobody adopted (`disk` != manifest `sha256`, or on disk without a manifest
    entry) is never overwritten or removed -- it is `dirty`, unless `force`. Everything else whose version
    moved or that is new is fetched; what the tree no longer names is
    removed."""
    fetch, remove, dirty = [], [], []
    names = {}
    for t in tree:
        names[t["path"]] = t
    for path in sorted(names):
        t = names[path]
        m = manifest.get(path)
        on = disk.get(path)
        # a file on disk the manifest never wrote (a tool made it, nobody
        # adopted it) is a tool change too (Review J M-3)
        touched = (m is not None and on != m.get("sha256")) or (m is None and on is not None)
        if m is not None and v12(m.get("version")) == v12(t.get("version")) and not touched:
            continue
        if touched and not force:
            dirty.append(path)
            continue
        fetch.append({"path": path, "file": t["file"], "version": v12(t.get("version"))})
    for path in sorted(manifest):
        if path in names:
            continue
        m = manifest[path]
        on = disk.get(path)
        if on is not None and on != m.get("sha256") and not force:
            dirty.append(path)
            continue
        remove.append(path)
    return {"fetch": fetch, "remove": remove, "dirty": sorted(dirty)}


def changes_of(manifest, found):
    """The difference between what was written (`manifest`) and what the
    directory holds after a run (`found`: `{path: sha256}`, ignored paths
    already left out): `modified`, `created`, `deleted`, in path order."""
    out = []
    for path in sorted(set(manifest) | set(found)):
        m = manifest.get(path)
        f = found.get(path)
        if m is None:
            out.append({"path": path, "kind": "created", "sha256": f})
        elif f is None:
            out.append({"path": path, "kind": "deleted", "file": m.get("file"),
                        "base": v12(m.get("version"))})
        elif f != m.get("sha256"):
            out.append({"path": path, "kind": "modified", "file": m.get("file"),
                        "base": v12(m.get("version")), "sha256": f})
    return out


def split_changes(changes, auto, first_id):
    """Every change as a numbered entry of `runs.changes`; with `auto`, the
    `modified` ones are to be adopted at once and the rest stays a proposal
    (OR-FJ-G3: a created or deleted file is always a proposal)."""
    out = []
    n = first_id
    for c in changes:
        e = dict(c, id=n, state="open")
        if auto and c["kind"] == "modified":
            e["state"] = "auto"
        out.append(e)
        n += 1
    return out


def tail(data, n=TAIL_BYTES):
    """The last `n` bytes of a stream as text."""
    if not isinstance(data, (bytes, bytearray)):
        data = str(data or "").encode("utf-8", "replace")
    return bytes(data[-n:]).decode("utf-8", "replace")


def pick(changes, ids):
    """The open entries `ids` names (a list of ids, or 'all'), and the ids
    that name nothing open."""
    open_ = [c for c in changes if c.get("state") == "open"]
    if ids == "all":
        return open_, []
    want = []
    for i in ids if isinstance(ids, list) else []:
        try:
            want.append(int(i))
        except Exception:
            want.append(i)
    got = [c for c in open_ if c.get("id") in want]
    have = set(c.get("id") for c in got)
    return got, [i for i in want if i not in have]


# ================================================================ PLUMBING
def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def ago(ms):
    t = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(milliseconds=ms)
    return t.strftime(FMT)


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("projection/mat: %s\n" % reason)
    emit([])


def knob(name, default):
    v = P.get(name, default)
    if isinstance(default, list):
        return jload(v, default) if not isinstance(v, list) else v
    return v if v is not None else default


def sel(table, columns, where=None, limit=ROW_LIMIT):
    a = {"operation": "select", "table": table, "columns": columns, "limit": limit}
    if where:
        a["where"] = where
    return a


def ins(table, row):
    return {"operation": "insert", "table": table, "row": row}


def upd(table, setv, where):
    return {"operation": "update", "table": table, "set": setv, "where": where}


def dele(table, where):
    return {"operation": "delete", "table": table, "where": where}


def store(ops, phase):
    """One bundle to `./store`; the store edge lifts `phase` into
    `context.cur_phase` and `reply_cell` into `cur_origin`."""
    return {"header": {"route": "mat_store", "phase": phase, "reply_cell": ME},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": "", "rows_affected": 0}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if not isinstance(r, dict):
                continue
            leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                 {"payload": None, "error_code": "", "rows_affected": 0})
            leg["error_code"] = str(r.get("error_code") or "")
            leg["rows_affected"] = int(r.get("rows_affected") or 0)
    elif len(out) == 1:
        leg = next(iter(out.values()))
        leg["error_code"] = str(hop.get("error_code") or "")
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def sha_file(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        while True:
            b = f.read(HASH_CHUNK)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def inside(top, p):
    """Whether `p` resolves (through every symlink) to a place below `top`."""
    t = os.path.realpath(top)
    r = os.path.realpath(p)
    return r == t or r.startswith(t + os.sep)


def disk_sha(wsdir, root, path):
    rel = rel_of(path, root)
    if rel is None:
        return None
    p = os.path.join(wsdir, rel)
    if not os.path.isfile(p) or not inside(wsdir, p):
        return None
    try:
        return sha_file(p)
    except OSError:
        return None


def scan(wsdir, root, globs):
    """Every file under the workspace directory as `{space path: sha256}`,
    ignored paths left out. A symlink is never followed into a directory;
    one that points at a file inside the directory counts as that file's
    content, any other is only named in `skipped`."""
    found, skipped = {}, []
    for top, dirs, files in os.walk(wsdir, followlinks=False):
        reld = os.path.relpath(top, wsdir)
        reld = "" if reld == "." else reld
        keep = []
        for dn in dirs:
            r = (reld + "/" + dn) if reld else dn
            if os.path.islink(os.path.join(top, dn)):
                if not ignored(r, globs):
                    skipped.append(path_of(r, root))
                continue
            if not ignored(r + "/x", globs):
                keep.append(dn)
        dirs[:] = keep
        for fn in files:
            r = (reld + "/" + fn) if reld else fn
            if ignored(r, globs):
                continue
            p = os.path.join(top, fn)
            if os.path.islink(p) and not (inside(wsdir, p) and os.path.isfile(p)):
                skipped.append(path_of(r, root))
                continue
            if not os.path.isfile(p):
                skipped.append(path_of(r, root))
                continue
            try:
                found[path_of(r, root)] = sha_file(p)
            except OSError:
                skipped.append(path_of(r, root))
    return found, sorted(skipped)


def make_dirs(wsdir, rel):
    """Make the directories of `rel` below `wsdir` one component at a time and
    hand back the parent. A component that is a symlink or no directory is
    refused BEFORE anything is made: a tool may have planted `sub -> <outside>`,
    and `os.makedirs` would follow it and make directories out there first
    (Review J I-2)."""
    d = wsdir
    for part in rel.split("/")[:-1]:
        d = os.path.join(d, part)
        if os.path.islink(d):
            raise OSError("a symlink on the way: " + rel)
        if not os.path.exists(d):
            os.mkdir(d)
        elif not os.path.isdir(d):
            raise OSError("no directory on the way: " + rel)
    return d


def put_file(wsdir, rel, src):
    """Move the staged bytes `src` to `<wsdir>/<rel>`, directories made on
    the way; never through a symlink out of the workspace directory."""
    dst = os.path.join(wsdir, rel)
    parent = make_dirs(wsdir, rel)
    if not inside(wsdir, parent):
        raise OSError("outside the workspace directory: " + rel)
    if os.path.islink(dst):
        os.unlink(dst)
    os.replace(src, dst)


def drop_file(wsdir, rel):
    p = os.path.join(wsdir, rel)
    if not inside(wsdir, os.path.dirname(p)):
        return
    if os.path.islink(p) or os.path.isfile(p):
        os.unlink(p)
    # empty directories left behind go too, never the workspace directory
    q = os.path.dirname(p)
    while q != wsdir and inside(wsdir, q):
        try:
            os.rmdir(q)
        except OSError:
            break
        q = os.path.dirname(q)


def stage_path(base, sub):
    return os.path.join(base, STAGE, re.sub(r"[^A-Za-z0-9._-]", "_", sub))


# ================================================================ JOBS
def job_ops(job, first=False):
    row = {"op_id": job["id"], "cell": ME, "phase": "job", "body": json.dumps(job), "at": now()}
    head = ins("pending", row) if first else upd(
        "pending", {"body": row["body"], "at": row["at"]},
        {"op_id": job["id"], "cell": ME, "phase": "job"})
    return [("j-put", head), ("j-echo", sel("pending", ["phase", "body"],
                                            {"op_id": job["id"], "cell": ME}))]


def save(job, ops=(), out=None, first=False, kind="step"):
    """Park the job and run `ops`; with `out`, the messages go out once the
    store confirmed the job row (phase `send`)."""
    job["out"] = list(out or [])
    return store(job_ops(job, first) + list(ops), ("send" if out else kind) + "|" + job["id"])


def answer_head(job):
    h = {"route": "answer", "op": job.get("op", ""), "op_id": job.get("op_id", ""),
         "caller": job.get("caller", "")}
    if job.get("name"):
        h["ws"] = job["name"]
    return h


def reply(job, payload):
    body = {"ok": True, "op": job["op"], "op_id": job["op_id"], "messages": []}
    body.update(payload)
    return dict(body, header=answer_head(job))


def refuse(job, code, message, **extra):
    err = {"code": code, "message": message}
    err.update(extra)
    return {"header": answer_head(job), "ok": False, "op": job.get("op", ""),
            "op_id": job.get("op_id", ""), "error": err, "messages": []}


def close(job, ops, answer):
    """The job's last bundle (its own `pending` rows go) and its answer."""
    ops = list(ops) + [("j-drop", dele("pending", {"op_id": job["id"], "cell": ME}))]
    return [store(ops, "done|" + job["id"]), answer]


def fail(job, code, message, **extra):
    return close(job, [], refuse(job, code, message, **extra))


def sub_id(job, tag):
    return "mat:%s:%s" % (job["id"], tag)


def ask(job, route, op, file, args, tag):
    """One request to the space: `in_ws`, `in_read` or `in_write`, answered on
    `answer` with `caller` 'projection', back on `in_answer`."""
    h = {"route": route, "op": op, "op_id": sub_id(job, tag), "caller": CALLER,
         "ws": job.get("name") or job["ref"]}
    msg = {"header": h, "op": op, "args": args, "messages": []}
    if file:
        msg["file"] = file
    job.setdefault("await", []).append(tag)
    return msg


def base_dir():
    b = str(knob("base_path", "") or "")
    return b.rstrip("/") if b != "/" else b


def probe(base):
    """A write probe under `base`: the sandbox grants `base_path` or nothing,
    and a projection that cannot write must say so before it starts."""
    try:
        os.makedirs(os.path.join(base, STAGE), exist_ok=True)
        p = os.path.join(base, STAGE, "probe-" + secrets.token_hex(4))
        with open(p, "wb") as f:
            f.write(b"probe")
        os.unlink(p)
        return True
    except OSError:
        return False


def base_problem(base):
    code = check_base(base, colony_root(os.getcwd(), os.path.exists))
    if code:
        return code
    if colony_above(base, os.path.exists):
        return "bad_base_path"
    if not os.path.isdir(base) or not probe(base):
        return "bad_base_path"
    return ""


# ------------------------------------------------------------------ steps
def after_tree(job, ans):
    """`ws_tree` answered: the name, root and files of the workspace."""
    if not ans.get("ok"):
        e = ans.get("error") or {}
        return fail(job, str(e.get("code") or "ws_unknown"), str(e.get("message") or ""))
    name = str(ans.get("name") or (ans.get("header") or {}).get("ws") or "")
    if not dir_name(name):
        return fail(job, "bad_request", "workspace %r cannot name a directory" % name)
    job["name"] = name
    job["root"] = str(ans.get("root") or "/")
    tree = []
    bad = []
    for f in ans.get("files") or []:
        if rel_of(str(f.get("path") or ""), job["root"]) is None:
            bad.append(str(f.get("path") or ""))
            continue
        tree.append({"path": f["path"], "file": f.get("file"), "version": v12(f.get("version"))})
    job["tree"] = tree
    job["bad"] = bad
    ops = [("proj", sel("proj", ["ws", "dir", "manifest"], {"ws": name}, 1))]
    if job["op"] == "ws_adopt":
        ops.append(("run", sel("runs", ["run", "ws", "changes"], {"run": job["args"]["run"]}, 1)))
    job["step"] = "loaded"
    return [save(job, ops)]


def wsdir_of(job):
    return os.path.join(base_dir(), job["name"])


def after_load(job, lg):
    got = rows(lg, "proj")
    job["has_proj"] = bool(got)
    manifest = jload(got[0].get("manifest"), {}) if got else {}
    job["manifest"] = manifest
    wsdir = wsdir_of(job)
    if job["op"] == "ws_adopt":
        r = rows(lg, "run")
        if not r or str(r[0].get("ws") or "") != job["name"]:
            return fail(job, "run_unknown", "no run %r in workspace %r" % (job["args"]["run"], job["name"]))
        return adopt_start(job, jload(r[0].get("changes"), []))
    try:
        # a tool of another workspace may have planted `<base>/<name>` as a
        # symlink; the directory is never reached through one (Review J I-2)
        if os.path.islink(wsdir):
            raise OSError("the workspace directory is a symlink")
        os.makedirs(wsdir, exist_ok=True)
    except OSError as e:
        return fail(job, "bad_base_path", "cannot make the workspace directory: %s" % e)
    disk = {}
    for p in set(manifest) | set(t["path"] for t in job["tree"]):
        disk[p] = disk_sha(wsdir, job["root"], p)
    plan = plan_materialize(job["tree"], manifest, disk, bool(job["args"].get("force")))
    if job["op"] == "ws_exec" and plan["dirty"]:
        return fail(job, "dirty_projection", "the directory holds changes nobody adopted",
                    dirty=plan["dirty"])
    job["plan"] = plan
    out = []
    for i, f in enumerate(plan["fetch"]):
        out.append(ask(job, "in_read", "raw", "%s@%s" % (f["file"], f["version"]), {}, "f%d" % i))
    job["step"] = "fetched"
    if not out:
        return materialized(job, {})
    return [save(job, out=out)]


def materialized(job, answers):
    """Every fetch answered: staged bytes into place, removals, manifest."""
    plan = job["plan"]
    wsdir = wsdir_of(job)
    base = base_dir()
    manifest = dict(job["manifest"])
    written = 0
    failed = []
    for i, f in enumerate(plan["fetch"]):
        tag = "f%d" % i
        a = answers.get(tag) or {}
        src = stage_path(base, sub_id(job, tag))
        rel = rel_of(f["path"], job["root"])
        if not a.get("ok") or not os.path.isfile(src):
            failed.append({"path": f["path"], "code": str((a.get("error") or {}).get("code") or "fetch_failed")})
            continue
        sha = sha_file(src)
        if v12(sha) != f["version"]:
            os.unlink(src)
            failed.append({"path": f["path"], "code": "corrupt"})
            continue
        try:
            put_file(wsdir, rel, src)
        except OSError:
            failed.append({"path": f["path"], "code": "outside_root"})
            continue
        manifest[f["path"]] = {"file": f["file"], "version": f["version"], "sha256": sha}
        written += 1
    for path in plan["remove"]:
        rel = rel_of(path, job["root"])
        if rel is not None:
            drop_file(wsdir, rel)
        manifest.pop(path, None)
    job["manifest"] = manifest
    ops = [proj_op(job)]
    if job["op"] == "ws_materialize":
        payload = {"ws": job["name"], "dir": wsdir, "written": written,
                   "removed": len(plan["remove"]), "dirty": plan["dirty"]}
        failed += [{"path": p, "code": "outside_root"} for p in job.get("bad") or []]
        if failed:
            payload["failed"] = failed
        return close(job, ops, reply(job, payload))
    if failed:
        return close(job, ops, refuse(job, "materialize_failed", "a file could not be laid out",
                                      failed=failed))
    job["has_proj"] = True
    a = job["args"]
    run_msg = {"header": {"route": "in_run", "op_id": sub_id(job, "x")},
               "argv": a["argv"], "cwd": wsdir, "messages": []}
    if a.get("timeout_ms") is not None:
        run_msg["timeout_ms"] = a["timeout_ms"]
    job.setdefault("await", []).append("x")
    job["step"] = "ran"
    return [save(job, ops, out=[run_msg])]


def proj_op(job):
    row = {"dir": wsdir_of(job), "manifest": json.dumps(job["manifest"]), "at": now()}
    if job.get("has_proj"):
        return ("p-put", upd("proj", row, {"ws": job["name"]}))
    job["has_proj"] = True
    return ("p-put", ins("proj", dict(row, ws=job["name"])))


def after_run(job, ran):
    """The program ended: read the directory once and sort what it did."""
    wsdir = wsdir_of(job)
    if not ran.get("ok"):
        e = ran.get("error") or {}
        return fail(job, str(e.get("code") or "exec_failed"), str(e.get("message") or ""))
    found, skipped = scan(wsdir, job["root"], knob("ignore", [".git/**", "target/**"]))
    changes = changes_of(job["manifest"], found)
    auto = ran.get("exit") == 0 and auto_hit(job["args"]["argv"], knob("auto_adopt", ["cargo fmt", "rustfmt"]))
    entries = split_changes(changes, auto, 1)
    run = "run-" + secrets.token_hex(6)
    job["run"] = run
    job["ran"] = {"exit": ran.get("exit"), "out_tail": str(ran.get("out_tail") or ""),
                  "err_tail": str(ran.get("err_tail") or "")}
    job["skipped"] = skipped
    job["changes"] = entries
    ops = [("r-ins", ins("runs", {"run": run, "ws": job["name"],
                                  "argv": json.dumps(job["args"]["argv"]),
                                  "exit": str(ran.get("exit")),
                                  "out_tail": job["ran"]["out_tail"],
                                  "err_tail": job["ran"]["err_tail"],
                                  "changes": json.dumps(entries), "at": now()}))]
    todo = [c for c in entries if c["state"] == "auto"]
    for c in todo:
        c["state"] = "open"
    return adopt_send(job, todo, ops)


def adopt_start(job, entries):
    got, unknown = pick(entries, job["args"].get("ids"))
    job["changes"] = entries
    job["run"] = job["args"]["run"]
    job["unknown"] = unknown
    return adopt_send(job, got, [])


def adopt_send(job, todo, ops):
    """One write to the space per change taken over, all at once; the
    answers come back on `in_answer` and `adopt_done` reads them together."""
    wsdir = wsdir_of(job)
    out = []
    job["adopting"] = []
    gone = []
    for c in todo:
        tag = "w%d" % c["id"]
        rel = rel_of(c["path"], job["root"])
        p = os.path.join(wsdir, rel) if rel else ""
        if c["kind"] == "deleted":
            out.append(ask(job, "in_write", "remove", c["file"], {"base": c["base"]}, tag))
        else:
            if not p or not inside(wsdir, p):
                gone.append({"id": c["id"], "path": c["path"], "code": "outside_root"})
                continue
            if not os.path.isfile(p):
                gone.append({"id": c["id"], "path": c["path"], "code": "gone"})
                continue
            # the bytes are frozen in the stage now and read into the request
            # only when it leaves (phase `send`): the parked job stays small,
            # and what is sent is what `sent` hashes
            src = stage_path(base_dir(), sub_id(job, tag))
            try:
                os.makedirs(os.path.dirname(src), exist_ok=True)
                with open(p, "rb") as f:
                    data = f.read()
                with open(src, "wb") as f:
                    f.write(data)
            except OSError:
                gone.append({"id": c["id"], "path": c["path"], "code": "gone"})
                continue
            c["sent"] = hashlib.sha256(data).hexdigest()
            if c["kind"] == "modified":
                out.append(ask(job, "in_write", "overwrite", c["file"],
                               {"base": c["base"], "b64_stage": tag}, tag))
            else:
                out.append(ask(job, "in_write", "create", "",
                               {"path": c["path"], "b64_stage": tag}, tag))
        job["adopting"].append({"id": c["id"], "tag": tag, "sent": c.get("sent", "")})
    job["gone"] = gone
    job["step"] = "adopted"
    if not out:
        return adopt_done(job, {}, ops)
    return [save(job, ops, out=out)]


def adopt_done(job, answers, ops=()):
    manifest = dict(job["manifest"])
    by_id = {c["id"]: c for c in job["changes"]}
    adopted, failed = [], list(job.get("gone") or [])
    for a in job["adopting"]:
        c = by_id[a["id"]]
        ans = answers.get(a["tag"]) or {}
        if not ans.get("ok"):
            e = ans.get("error") or {}
            failed.append({"id": c["id"], "path": c["path"], "code": str(e.get("code") or "write_failed")})
            continue
        c["state"] = "adopted"
        if c["kind"] == "deleted":
            manifest.pop(c["path"], None)
            adopted.append({"path": c["path"], "file": c["file"], "kind": "deleted"})
            continue
        f = str(ans.get("file") or c.get("file") or "")
        v = v12(ans.get("version"))
        c["file"] = f
        manifest[c["path"]] = {"file": f, "version": v, "sha256": a["sent"]}
        adopted.append({"path": c["path"], "file": f, "version": v})
    job["manifest"] = manifest
    ops = list(ops) + [proj_op(job),
                       ("r-put", upd("runs", {"changes": json.dumps(job["changes"])},
                                     {"run": job["run"]}))]
    if job["op"] == "ws_adopt":
        payload = {"ws": job["name"], "run": job["run"], "adopted": adopted}
        if failed:
            payload["failed"] = failed
        if job.get("unknown"):
            payload["unknown"] = job["unknown"]
        return close(job, ops, reply(job, payload))
    proposals = [{"id": c["id"], "path": c["path"], "kind": c["kind"]}
                 for c in job["changes"] if c["state"] == "open"]
    payload = {"ws": job["name"], "run": job["run"], "exit": job["ran"]["exit"],
               "out_tail": job["ran"]["out_tail"], "err_tail": job["ran"]["err_tail"],
               "adopted": [{"path": x["path"], "version": x["version"]} for x in adopted if "version" in x],
               "proposals": proposals}
    if failed:
        payload["failed"] = failed
    if job.get("skipped"):
        payload["skipped"] = job["skipped"]
    return close(job, ops, reply(job, payload))


def advance(job, answers, lg):
    step = job.get("step")
    if step == "tree":
        return after_tree(job, answers.get("t") or {})
    if step == "loaded":
        return after_load(job, lg)
    if step == "fetched":
        return materialized(job, answers)
    if step == "ran":
        return after_run(job, answers.get("x") or {})
    if step == "adopted":
        return adopt_done(job, answers)
    park("job %s in unknown step %r -- dropped" % (job.get("id"), step))


# ================================================================ LANES
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")

if lane == "in_proj":
    op = str(hop.get("op") or d.get("op") or "")
    args = d.get("args") if isinstance(d.get("args"), dict) else {}
    job = {"id": "mj-" + secrets.token_hex(8), "op": op,
           "op_id": str(hop.get("op_id") or ""), "caller": str(hop.get("caller") or ""),
           "ref": str(hop.get("ws") or args.get("ws") or ""), "args": args}
    if not job["op_id"]:
        emit([refuse(job, "bad_request", "a request carries hop.op_id")])
    if op not in OPS:
        emit([refuse(job, "unknown_op", "this lane serves " + ", ".join(OPS))])
    if not job["ref"]:
        emit([refuse(job, "bad_request", "name the workspace in hop.ws or args.ws")])
    base = base_dir()
    problem = base_problem(base)
    if problem:
        emit([refuse(job, problem, "base_path must be an absolute, writable directory outside "
                     "the colony, granted to this cell's sandbox by the owner's override")])
    if op == "ws_exec":
        argv = args.get("argv")
        if not isinstance(argv, list) or not argv or not all(isinstance(x, str) and x for x in argv):
            emit([refuse(job, "bad_request", "ws_exec takes argv, a list of strings")])
        # exec_allow is asked HERE, before anything is laid out or started
        # (OR-FJ-G2: default empty = every program refused).
        if not allowed(argv, knob("exec_allow", [])):
            emit([refuse(job, "not_allowed", "%r is not in exec_allow" % argv[0])])
        t = args.get("timeout_ms")
        if t is not None and (not isinstance(t, int) or isinstance(t, bool) or t <= 0):
            emit([refuse(job, "bad_request", "timeout_ms is a positive number")])
    if op == "ws_adopt":
        ids = args.get("ids")
        if not str(args.get("run") or ""):
            emit([refuse(job, "bad_request", "ws_adopt takes run")])
        if ids != "all" and not isinstance(ids, list):
            emit([refuse(job, "bad_request", "ids is a list of proposal ids or 'all'")])
    tree = ask(job, "in_ws", "ws_tree", "", {}, "t")
    job["step"] = "tree"
    # a job whose answer never came (a timed-out cell answers without a
    # route, B1-PP-14) is cleared by the next request instead of piling up
    # (OR-FJ-64)
    stale = ("j-stale", dele("pending", {"cell": ME, "at": {"lt": ago(JOB_TTL_MS)}}))
    emit([save(job, [stale], out=[tree], first=True)])

if lane in ("in_answer", "ran"):
    oid = str(hop.get("op_id") or "")
    parts = oid.split(":")
    if len(parts) != 3 or parts[0] != "mat":
        park("answer with foreign op_id %r -- dropped" % oid)
    jid, tag = parts[1], parts[2]
    ans = {k: v for k, v in d.items() if k not in ("messages", "b64")}
    if isinstance(d.get("b64"), str):
        # the bytes go to the stage at once; the parked answer stays small
        try:
            data = base64.b64decode(d["b64"], validate=True)
            src = stage_path(base_dir(), oid)
            os.makedirs(os.path.dirname(src), exist_ok=True)
            with open(src, "wb") as f:
                f.write(data)
        except Exception as e:
            ans = {"ok": False, "error": {"code": "stage_failed", "message": str(e)}}
    ans["header"] = {"ws": str(hop.get("ws") or "")}
    emit([store([("a-put", ins("pending", {"op_id": jid, "cell": ME, "phase": "a:" + tag,
                                          "body": json.dumps(ans), "at": now()})),
                 ("j-echo", sel("pending", ["phase", "body"], {"op_id": jid, "cell": ME}))],
                "got|" + jid)])

if lane:
    park("unknown lane %r -- dropped" % lane)
if not hop.get("operation"):
    park("a message with neither a lane nor a store answer -- dropped")

kind, _, jid = phase.partition("|")
if kind == "done":
    emit([])
lg = legs(d)
bad = sorted(k for k, v in lg.items() if v["error_code"])
job, answers = None, {}
for r in rows(lg, "j-echo"):
    ph = str(r.get("phase") or "")
    if ph == "job":
        job = jload(r.get("body"), {}) or None
    elif ph.startswith("a:"):
        answers[ph[2:]] = jload(r.get("body"), {})
if not isinstance(job, dict):
    park("store answer in phase %r without its job -- dropped" % phase)
if bad:
    sys.stderr.write("projection/mat: store refused %s in phase %s\n" % (", ".join(bad), phase))
    emit(fail(job, "store_error", "the projection's store refused a write; try again later"))

if kind == "send":
    out = list(job.get("out") or [])
    for m in out:
        a = m.get("args") if isinstance(m.get("args"), dict) else {}
        tag = a.pop("b64_stage", None)
        if tag:
            src = stage_path(base_dir(), sub_id(job, tag))
            try:
                with open(src, "rb") as f:
                    a["b64"] = base64.b64encode(f.read()).decode("ascii")
                os.unlink(src)
            except OSError as e:
                # the frozen bytes are gone: the job answers instead of the
                # script dying and leaving its caller waiting (Review J M-2)
                emit(fail(job, "stage_failed", "staged bytes of %s are gone: %s" % (tag, e)))
    emit(out)
if kind == "got":
    wait = job.get("await") or []
    if not wait or any(t not in answers for t in wait):
        emit([])
    job["await"] = []
    drop = ("a-drop", dele("pending", {"op_id": job["id"], "cell": ME,
                                        "phase": {"in": ["a:" + t for t in wait]}}))
    out = advance(job, answers, lg)
    # the answers read now are gone from the next echo
    first = out[0] if out else None
    if isinstance(first, dict) and first.get("header", {}).get("route") == "mat_store":
        first["messages"].insert(0, {"origin": "assistant", "type": "tool_call", "id": drop[0],
                                     "text": json.dumps(drop[1])})
    emit(out)
if kind == "step":
    emit(advance(job, answers, lg))
park("store answer in unknown phase %r -- dropped" % phase)
